"""
    Compute RS capacity for target density
    """
def compute_capacity(n_seats: Any, aw2_capacity: Any, target_density: Any) -> object {
    return ((((aw2_capacity - n_seats) * target_density) / 4) + n_seats);
}

test_blocks:
test "t0" {
    assert (compute_capacity(2, 2, 0.3) == 2);;
}

test "t1" {
    assert (
        compute_capacity(100000000000000000, 100000000000000000, 0.01)
        == 100000000000000000
    );;
}

test "t2" {
    assert (compute_capacity(100, 500, 1) == 200);;
}

test "t3" {
    assert (compute_capacity(3, 3, 0.3) == 3);;
}

test "t4" {
    assert (compute_capacity(0, 0, 0) == 0);;
}

test "t5" {
    assert (compute_capacity(1000000, 1000000, 0.01) == 1000000);;
}
